{"hypotheses":[{"nl":"Remove every row consisting entirely of 1s; if a full column of 5s exists, keep only columns before it, otherwise keep all columns; recolor remaining 1s to 2 and everything else to 0.","code":"def transform(grid):
    rows=[row for row in grid if not all(x==1 for x in row)]
    if not rows: rows=grid
    d=next((c for c in range(len(grid[0])) if all(row[c]==5 for row in grid)),len(grid[0]))
    return [[2 if x==1 else 0 for x in row[:d]] for row in rows]"},{"nl":"Trim the maximal bottom block of all-one rows, and use a full-5 column as a separator to crop its left panel; without such a separator preserve the full width, then map 1 to 2.","code":"def transform(grid):
    n=len(grid)
    while n and all(x==1 for x in grid[n-1]): n-=1
    if n==0:n=len(grid)
    d=next((c for c in range(len(grid[0])) if all(grid[r][c]==5 for r in range(len(grid)))),len(grid[0]))
    return [[2 if x==1 else 0 for x in grid[r][:d]] for r in range(n)]"},{"nl":"Output all non-all-one rows, but crop at the first column that is uniformly 5 only when it exists; encode 1 cells as 2 and all other cells as 0.","code":"def transform(grid):
    keep=[row for row in grid if any(x!=1 for x in row)]
    sep=None
    for c in range(len(grid[0])):
        if all(row[c]==5 for row in grid): sep=c; break
    if sep is None: sep=len(grid[0])
    return [[2 if v==1 else 0 for v in row[:sep]] for row in keep]"},{"nl":"Delete the uniform all-1 tail rows; the output width is the input width unless a solid 5 divider column marks a left-hand panel, and recolor occupied cells.","code":"def transform(grid):
    h=len(grid)
    while h>0 and set(grid[h-1])=={1}: h-=1
    h=h or len(grid)
    cuts=[c for c in range(len(grid[0])) if {grid[r][c] for r in range(len(grid))}=={5}]
    w=min(cuts) if cuts else len(grid[0])
    return [[2 if grid[r][c]==1 else 0 for c in range(w)] for r in range(h)]"},{"nl":"Keep the nonuniform rows and, when present, the portion before a column made solely of color 5; otherwise keep the whole rectangle, replacing 1 with 2.","code":"def transform(grid):
    rr=[r for r in grid if not all(v==1 for v in r)]
    cc=len(grid[0])
    for c in range(cc):
        if all(r[c]==5 for r in grid): cc=c; break
    return [[2 if v==1 else 0 for v in r[:cc]] for r in rr]"}]}

